import React,{useState} from 'react';import {supabase} from '../lib/supabase';import toast from 'react-hot-toast';import {useNavigate} from 'react-router-dom';
export default function ResetPassword(){const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [loading,setLoading]=useState(false);const navigate=useNavigate();const handleSubmit=async e=>{e.preventDefault();if(password!==confirm)return toast.error('Passwords do not match');if(password.length<6)return toast.error('Min 6 chars');setLoading(true);const {error}=await supabase.auth.updateUser({password});if(error)toast.error(error.message);else{toast.success('Password updated');navigate('/login');}setLoading(false);};return(<div className="min-h-screen flex items-center justify-center"><form onSubmit={handleSubmit} className="bg-white p-8 rounded-xl shadow-md w-96"><h1>Reset Password</h1><input type="password" placeholder="New Password" value={password} onChange={e=>setPassword(e.target.value)} className="w-full p-3 border rounded mb-4" required/><input type="password" placeholder="Confirm Password" value={confirm} onChange={e=>setConfirm(e.target.value)} className="w-full p-3 border rounded mb-4" required/><button disabled={loading} className="w-full bg-green-600 text-white p-3 rounded">{loading?'Updating...':'Update Password'}</button></form></div>);}
